// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Minimal ERC20 Interface
interface IERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

contract Bbillionaire {
    // ---------- Ownership & Security ----------
    address public owner;
    uint256 private _status;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }
    modifier nonReentrant() {
        require(_status != _ENTERED, "Reentrancy");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }

    // ---------- Core Settings ----------
    IERC20 public jsav;
    address public rootReferrer;
    address public feeWallet;

    uint256 public constant MONTH = 30 days;
    uint256 public constant BPS = 10000;
    uint256 public constant ROI_PERCENT = 8;     // 8% Monthly ROI
    uint256 public constant FEE_PERCENT = 10;    // 10% Extra Fee
    uint256 public constant CAP_MULTIPLIER = 2;  // 2x Cap per Investment

    uint256 public minInvestment = 100 * 1e18;       // 100 JSAV
    uint256 public maxInvestment = 100000 * 1e18;    // 100,000 JSAV
    uint256 public lifetimeLimit = 100000 * 1e18;    // 100,000 JSAV per address

    // ---------- Structs ----------
    struct User {
        address referrer;
        uint256 directs;
        uint256 totalInvested;
        uint256 bonusCursor;
        uint256 lastClaimAt;
        bool exists;
        bool held;
        bool blocked;
    }

    struct Investment {
        uint256 principal;
        uint256 startedAt;
        uint256 roiCredited;
        uint256 earned;     // Total ROI + Level Income ever credited
        uint256 unclaimed;
    }

    mapping(address => User) public users;
    mapping(address => Investment[]) public investments;

    // ---------- Events ----------
    event Invested(address indexed user, uint256 indexed investmentId, uint256 principal, uint256 fee);
    event ROIAccrued(address indexed user, uint256 indexed investmentId, uint256 amount);
    event LevelIncome(address indexed from, address indexed to, uint256 indexed investmentId, uint8 level, uint256 amount);
    event Claimed(address indexed user, uint256 indexed investmentId, uint256 amount);
    event ClaimedAll(address indexed user, uint256 amount, uint256 count);
    event RewardsFunded(address indexed funder, uint256 amount);
    event UserHeld(address indexed user, bool held);
    event UserBlocked(address indexed user, bool blocked);
    event FeeWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event OwnershipTransferred(address indexed oldOwner, address indexed newOwner);

    // ---------- Constructor ----------
    constructor(address _feeWallet, address _rootReferrer) {
        require(_feeWallet != address(0), "Invalid fee wallet");
        require(_rootReferrer != address(0), "Invalid root referrer");

        owner = msg.sender;
        _status = _NOT_ENTERED;

        // JSAV Token on BSC Mainnet (18 Decimals enforced)
        jsav = IERC20(0x418B7e6BBc48Ca93126c22A1e83b6420A4E0C6fD);
        require(jsav.decimals() == 18, "JSAV must be 18 decimals");

        feeWallet = _feeWallet;
        rootReferrer = _rootReferrer;
        users[_rootReferrer].exists = true;
    }

    // ---------- Views ----------
    function investmentCount(address account) external view returns (uint256) {
        return investments[account].length;
    }

    function nextClaimAt(address account) external view returns (uint256) {
        uint256 last = users[account].lastClaimAt;
        if (last == 0) return 0;
        uint256 next = last + MONTH;
        return block.timestamp >= next ? 0 : next;
    }

    function projectedUnclaimed(address account, uint256 investmentId) external view returns (uint256) {
        Investment storage p = investments[account][investmentId];
        return p.unclaimed + _newROI(p);
    }

    function isInvestmentCapped(address account, uint256 investmentId) external view returns (bool) {
        Investment storage p = investments[account][investmentId];
        return p.earned >= CAP_MULTIPLIER * p.principal;
    }

    // ---------- Invest ----------
    function invest(uint256 principal, address referrer) external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(principal >= minInvestment && principal <= maxInvestment, "Investment outside limits");
        require(user.totalInvested + principal <= lifetimeLimit, "Lifetime limit exceeded");

        if (!user.exists) {
            address parent = referrer == address(0) ? rootReferrer : referrer;
            require(parent != msg.sender, "Cannot refer yourself");
            require(users[parent].exists, "Referrer not registered");
            user.exists = true;
            user.referrer = parent;
            users[parent].directs++;
        }

        uint256 fee = (principal * FEE_PERCENT) / 100;
        uint256 cost = principal + fee;

        uint256 beforeBalance = jsav.balanceOf(address(this));
        _safeTransferFrom(address(jsav), msg.sender, address(this), cost);
        require(jsav.balanceOf(address(this)) - beforeBalance == cost, "Token transfer failed");

        _safeTransfer(address(jsav), feeWallet, fee);

        uint256 investmentId = investments[msg.sender].length;
        investments[msg.sender].push(Investment(principal, block.timestamp, 0, 0, 0));
        user.totalInvested += principal;

        emit Invested(msg.sender, investmentId, principal, fee);
    }

    // ---------- Accrue / Claim ----------
    function accrue(address investor, uint256 investmentId) external nonReentrant {
        require(!users[investor].blocked, "Investor blocked");
        _accrue(investor, investmentId);
    }

    function accrueAll(address investor) external nonReentrant {
        require(!users[investor].blocked, "Investor blocked");
        for (uint256 i = 0; i < investments[investor].length; i++) {
            _accrue(investor, i);
        }
    }

    function claim(uint256 investmentId) external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(user.lastClaimAt == 0 || block.timestamp >= user.lastClaimAt + MONTH, "Withdraw: once per 30 days");

        _accrue(msg.sender, investmentId);

        Investment storage p = investments[msg.sender][investmentId];
        uint256 amount = p.unclaimed;
        require(amount != 0, "Nothing to claim");

        p.unclaimed = 0;
        user.lastClaimAt = block.timestamp;
        _safeTransfer(address(jsav), msg.sender, amount);

        emit Claimed(msg.sender, investmentId, amount);
    }

    function claimAll() external nonReentrant {
        User storage user = users[msg.sender];
        require(!user.held && !user.blocked, "User restricted");
        require(user.lastClaimAt == 0 || block.timestamp >= user.lastClaimAt + MONTH, "Withdraw: once per 30 days");

        uint256 len = investments[msg.sender].length;
        require(len != 0, "No investments");

        uint256 total;
        uint256 count;
        for (uint256 i = 0; i < len; i++) {
            _accrue(msg.sender, i);
            Investment storage p = investments[msg.sender][i];
            if (p.unclaimed != 0) {
                total += p.unclaimed;
                p.unclaimed = 0;
                count++;
            }
        }
        require(total != 0, "Nothing to claim");

        user.lastClaimAt = block.timestamp;
        _safeTransfer(address(jsav), msg.sender, total);

        emit ClaimedAll(msg.sender, total, count);
    }

    // ---------- Funding / Admin ----------
    function fundRewards(uint256 amount) external nonReentrant {
        require(amount != 0, "Zero amount");
        uint256 beforeBalance = jsav.balanceOf(address(this));
        _safeTransferFrom(address(jsav), msg.sender, address(this), amount);
        require(jsav.balanceOf(address(this)) - beforeBalance == amount, "Token transfer failed");
        emit RewardsFunded(msg.sender, amount);
    }

    function setHeld(address account, bool held) external onlyOwner {
        require(account != address(0), "Invalid account");
        users[account].held = held;
        emit UserHeld(account, held);
    }

    function setBlocked(address account, bool blocked) external onlyOwner {
        require(account != address(0), "Invalid account");
        users[account].blocked = blocked;
        emit UserBlocked(account, blocked);
    }

    function setFeeWallet(address newWallet) external onlyOwner {
        require(newWallet != address(0), "Invalid fee wallet");
        address old = feeWallet;
        feeWallet = newWallet;
        emit FeeWalletUpdated(old, newWallet);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid owner");
        address old = owner;
        owner = newOwner;
        emit OwnershipTransferred(old, newOwner);
    }

    // ---------- Internal Logic ----------
    function _scheduledROI(Investment storage p) private view returns (uint256) {
        return (p.principal * ROI_PERCENT * (block.timestamp - p.startedAt)) / (100 * MONTH);
    }

    function _newROI(Investment storage p) private view returns (uint256) {
        uint256 cap = CAP_MULTIPLIER * p.principal;
        if (p.earned >= cap) return 0;
        uint256 remaining = cap - p.earned;
        uint256 scheduled = _scheduledROI(p);
        if (scheduled <= p.roiCredited) return 0;
        uint256 due = scheduled - p.roiCredited;
        return due < remaining ? due : remaining;
    }

    function _accrue(address investor, uint256 investmentId) private {
        Investment storage p = investments[investor][investmentId];
        uint256 roi = _newROI(p);
        if (roi == 0) return;

        p.roiCredited += roi;
        p.earned += roi;
        p.unclaimed += roi;
        emit ROIAccrued(investor, investmentId, roi);

        address upline = users[investor].referrer;
        for (uint8 level = 1; level <= 5 && upline != address(0); level++) {
            User storage recipient = users[upline];
            if (recipient.directs >= level && !recipient.held && !recipient.blocked) {
                uint256 rate = level == 1 ? 500 : level == 2 ? 300 : level == 3 ? 100 : 50;
                uint256 reward = (roi * rate) / BPS;
                if (reward != 0) _creditLevelIncome(investor, upline, level, reward);
            }
            upline = recipient.referrer;
        }
    }

    function _bonusRoom(Investment storage p) private view returns (uint256) {
        uint256 cap = CAP_MULTIPLIER * p.principal;
        if (p.earned >= cap) return 0;
        uint256 remaining = cap - p.earned;
        uint256 scheduled = _scheduledROI(p);
        uint256 unbooked = scheduled > p.roiCredited ? scheduled - p.roiCredited : 0;
        return remaining > unbooked ? remaining - unbooked : 0;
    }

    function _creditLevelIncome(address from, address recipient, uint8 level, uint256 amount) private {
        User storage user = users[recipient];
        Investment[] storage positions = investments[recipient];
        uint256 index = user.bonusCursor;

        while (amount != 0 && index < positions.length) {
            Investment storage p = positions[index];
            uint256 room = _bonusRoom(p);
            if (room == 0) { index++; continue; }

            uint256 credit = amount < room ? amount : room;
            p.earned += credit;
            p.unclaimed += credit;
            amount -= credit;

            emit LevelIncome(from, recipient, index, level, credit);
            if (credit == room) index++;
        }
        user.bonusCursor = index;
    }

    // ---------- Safe Token Transfers ----------
    function _safeTransfer(address token, address to, uint256 amount) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "Transfer failed");
    }

    function _safeTransferFrom(address token, address from, address to, uint256 amount) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "TransferFrom failed");
    }
}

